// backend/src/core/ai/files/file-reader.routes.ts
import { FastifyPluginAsync } from 'fastify';
import type { ReadFileRequest, ReadFileResponse } from './file-reader.types';
import { fileReaderService } from './file-reader.service';

const fileReaderRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.post<{ Body: ReadFileRequest }>('/read', async (req, reply) => {
    if (!req.user || !req.tenant) {
      return reply.status(401).send({ error: 'Não autenticado' });
    }

    const { path: filePath } = req.body;

    if (!filePath || typeof filePath !== 'string') {
      return reply.status(400).send({ error: 'path é obrigatório e deve ser uma string' });
    }

    try {
      const result = fileReaderService.readFile(filePath);

      const response: ReadFileResponse = {
        content: result.content,
        path: filePath,
        truncated: result.truncated,
      };

      return reply.send(response);
    } catch (error: any) {
      fastify.log.error({ err: error }, 'Erro ao ler arquivo');
      
      if (error.message.includes('bloqueado') || error.message.includes('fora da raiz')) {
        return reply.status(403).send({ error: error.message });
      }
      
      if (error.message.includes('não encontrado')) {
        return reply.status(404).send({ error: error.message });
      }

      return reply.status(500).send({ error: 'Erro ao ler arquivo' });
    }
  });
};

export default fileReaderRoutes;















